<template>
  <div class="access-page">
    <section class="page-heading"><div><p class="eyebrow">ACCESS & COLLABORATION</p><h1>下载配额与团队协作</h1><p>每天都有清晰的下载额度，团队资产通过邀请码加入并按角色协作。</p></div><a-button @click="router.push('/community')">返回作品社区</a-button></section>
    <a-row :gutter="18"><a-col :xs="24" :lg="9"><section class="quota-card"><div class="card-label"><span>今日下载配额</span><a-tag color="green">{{ quota?.quotaDate ? '今日有效' : '等待加载' }}</a-tag></div><div class="quota-number"><strong>{{ remaining }}</strong><span>/ {{ quota?.quotaLimit || 0 }} 次可用</span></div><a-progress :percent="percent" :show-info="false" stroke-color="var(--accent-hover)" trail-color="#e5eee6" /><div class="quota-foot"><span>已使用 {{ quota?.usedCount || 0 }} 次</span><span>{{ percent }}%</span></div></section></a-col><a-col :xs="24" :lg="15"><section class="invite-card"><div class="card-label"><div><span>加入团队空间</span><small>输入团队管理员发给你的邀请码</small></div><TeamOutlined /></div><a-input-search v-model:value="code" size="large" enter-button="兑换邀请码" placeholder="例如：PHOTO-2026" :loading="redeeming" @search="redeem" /><a-alert v-if="redeemed" class="redeemed-alert" type="success" show-icon message="邀请码兑换成功" description="你已经加入团队空间，可以在左侧导航查看团队资产。" /></section></a-col></a-row>
    <section class="invite-manager"><div class="manager-heading"><div><p class="eyebrow">TEAM ADMIN</p><h2>创建团队邀请码</h2><span>仅团队空间所有者或管理员可以生成邀请码。</span></div><TeamOutlined /></div><a-alert v-if="!teamSpaces.length" type="info" show-icon message="暂时没有可管理的团队空间" description="创建团队空间或先兑换其他管理员的邀请码后，这里会显示可用空间。" /><a-form v-else layout="vertical" :model="inviteForm" @finish="createInvite"><a-row :gutter="14"><a-col :xs="24" :sm="10"><a-form-item label="团队空间" name="spaceId" :rules="[{required:true,message:'请选择团队空间'}]"><a-select v-model:value="inviteForm.spaceId" style="width:100%" placeholder="选择团队空间"><a-select-option v-for="space in teamSpaces" :key="space.spaceId" :value="space.spaceId">{{ space.space?.spaceName || `团队空间 ${space.spaceId}` }}</a-select-option></a-select></a-form-item></a-col><a-col :xs="24" :sm="7"><a-form-item label="成员角色"><a-select v-model:value="inviteForm.spaceRole" style="width:100%"><a-select-option value="viewer">浏览者</a-select-option><a-select-option value="editor">编辑者</a-select-option></a-select></a-form-item></a-col><a-col :xs="24" :sm="7"><a-form-item label="最大使用次数"><a-input-number v-model:value="inviteForm.maxUses" :min="1" :max="100" style="width:100%" /></a-form-item></a-col></a-row><a-button type="primary" html-type="submit" :loading="creating">生成邀请码</a-button></a-form><a-alert v-if="createdInvite" class="created-code" type="success" show-icon message="邀请码已生成，请复制给团队成员" :description="createdInvite.code" /></section>
    <section class="rules"><h2>访问规则</h2><div class="rule-grid"><div><DownloadOutlined /><strong>每日配额</strong><p>下载公开作品会消耗当天额度，次日自动恢复。</p></div><div><SafetyOutlined /><strong>受限内容</strong><p>作者设置为受限的图片，需要获得对应空间权限。</p></div><div><TeamOutlined /><strong>团队邀请码</strong><p>邀请码由团队管理员创建，兑换后继承空间角色。</p></div></div></section>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { message } from 'ant-design-vue'; import { DownloadOutlined, SafetyOutlined, TeamOutlined } from '@ant-design/icons-vue'; import { useRouter } from 'vue-router'; import { createInvite as createInviteApi, getTodayQuota, listMyTeamSpaces, redeemInvite } from '@/api/photoCommunity'
const router=useRouter();type Quota={quotaLimit:number;usedCount:number;quotaDate?:string};const quota=ref<Quota>();const teamSpaces=ref<any[]>([]);const code=ref('');const redeeming=ref(false);const redeemed=ref(false);const creating=ref(false);const createdInvite=ref<any>();const inviteForm=reactive({spaceId:undefined as number|undefined,spaceRole:'viewer',maxUses:1})
const remaining=computed(()=>Math.max(0,(quota.value?.quotaLimit||0)-(quota.value?.usedCount||0)));const percent=computed(()=>{const limit=quota.value?.quotaLimit||0;return limit?Math.min(100,Math.round(((quota.value?.usedCount||0)/limit)*100)):0})
async function load(){try{const [quotaRes,spacesRes]:any[]=await Promise.all([getTodayQuota(),listMyTeamSpaces()]);if(quotaRes.data.code===0)quota.value=quotaRes.data.data;if(spacesRes.data.code===0)teamSpaces.value=(spacesRes.data.data||[]).filter((item:any)=>item.space?.spaceType===1&&(item.spaceRole==='admin'||item.space?.userId===item.userId))}catch{message.error('配额信息暂时无法加载')}}async function redeem(){if(!code.value.trim())return;redeeming.value=true;redeemed.value=false;try{const res:any=await redeemInvite({code:code.value.trim()});if(res.data.code===0){message.success('已加入团队');redeemed.value=true;code.value=''}else message.error(res.data.message)}finally{redeeming.value=false}}async function createInvite(){if(!inviteForm.spaceId)return;creating.value=true;try{const res:any=await createInviteApi(inviteForm);if(res.data.code===0){createdInvite.value=res.data.data;message.success('邀请码已生成')}else message.error(res.data.message)}finally{creating.value=false}}onMounted(load)
</script>
<style scoped>
.access-page{max-width:1100px;margin:0 auto}.page-heading{display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:30px}.eyebrow{margin:0 0 10px;color:var(--accent-hover);font-size:12px;font-weight:600;letter-spacing:2px}.page-heading h1{margin:0 0 10px;color:var(--text-1);font:400 clamp(38px,4.2vw,62px)/1.15 var(--font-display);letter-spacing:-.02em}.page-heading p:not(.eyebrow){margin:0;color:var(--text-3);line-height:1.7}.quota-card,.invite-card,.invite-manager{min-height:200px;padding:24px;background:var(--surface);border:1px solid var(--border);border-radius:8px}.quota-card{background:var(--accent-soft)}.card-label{display:flex;justify-content:space-between;align-items:start;color:var(--accent-ink);font-size:13px}.card-label small{display:block;margin-top:5px;color:var(--text-3);font-size:12px}.quota-number{display:flex;align-items:baseline;gap:8px;margin:28px 0 20px}.quota-number strong{color:var(--accent-ink);font-size:48px;line-height:1}.quota-number span{color:var(--text-3)}.quota-foot{display:flex;justify-content:space-between;margin-top:8px;color:var(--text-3);font-size:12px}.invite-card .card-label>span{font-size:17px;color:var(--accent-ink)}.invite-card .card-label>svg{font-size:22px;color:var(--accent-hover)}.invite-card :deep(.ant-input-search){margin-top:30px}.redeemed-alert,.created-code{margin-top:16px}.invite-manager{margin-top:18px;background:#f8fbf8}.manager-heading{display:flex;justify-content:space-between;margin-bottom:18px}.manager-heading h2{margin:0 0 5px;color:var(--accent-ink);font-size:20px}.manager-heading span{color:var(--text-3);font-size:12px}.manager-heading>svg{font-size:25px;color:var(--accent-hover)}.rules{margin-top:38px}.rules h2{margin:0 0 16px;color:var(--accent-ink);font-size:20px}.rule-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.rule-grid>div{display:grid;grid-template-columns:25px 1fr;column-gap:8px;padding:18px;background:var(--surface);border:1px solid var(--border);border-radius:8px}.rule-grid svg{grid-row:span 2;color:var(--accent-hover);font-size:20px}.rule-grid strong{color:var(--accent-ink);font-size:14px}.rule-grid p{margin:5px 0 0;color:var(--text-3);font-size:12px;line-height:1.6}@media(max-width:640px){.page-heading{display:block}.page-heading .ant-btn{margin-top:14px}.rule-grid{grid-template-columns:1fr}}
</style>
